function MyComponent() {
  const { subscribe, publish } = useWebSocketSync("checkpoint");
  useEffect(() => {
    const unsub = subscribe("checkpoint_ack", payload => console.log(payload));
    publish({ type: "checkpoint", ts: Date.now() });
    return unsub;
  }, []);
  return null;
}
```

